-- Attribute Testing: default 3 targets (name + image per target); align builder layout in research-frontend (single row grid).
UPDATE module_templates
SET
  description = 'Implicit association test with 3 targets and attribute classification',
  structure = '{"components":[{"id":"target-1-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":true,"order":1,"settings":{"groupLabel":"Target 1","description":"Yo can use an image or a name for this."}},{"id":"target-1-image","type":"file-upload","label":"Target 1 Image","order":2,"settings":{"groupLabel":"Target 1"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"target-2-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":true,"order":3,"settings":{"groupLabel":"Target 2","description":"Yo can use an image or a name for this."}},{"id":"target-2-image","type":"file-upload","label":"Target 2 Image","order":4,"settings":{"groupLabel":"Target 2"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"target-3-name","type":"input","label":"Name of the object","placeholder":{"enabled":true,"text":"Text the name here"},"required":false,"order":5,"settings":{"groupLabel":"Target 3","description":"Yo can use an image or a name for this."}},{"id":"target-3-image","type":"file-upload","label":"Target 3 Image","order":6,"settings":{"groupLabel":"Target 3"},"fileUpload":{"maxSizeMB":5,"acceptedFormats":["image/jpeg","image/png","image/gif"]}},{"id":"priming-time","type":"select","label":"Priming display time","value":"400","options":[{"label":"300 ms","value":"300"},{"label":"400 ms","value":"400"},{"label":"500 ms","value":"500"}],"order":7},{"id":"criteria","type":"ranking-list","label":"Criteria","required":true,"order":8,"settings":{"minItems":1,"maxItems":15,"hasImage":true}},{"id":"show-results","type":"checkbox","label":"Show results to respondents","value":"false","order":9},{"id":"exercise-instructions","type":"textarea","label":"Exercise instructions","placeholder":{"enabled":true,"text":"One of three objects appears each trial. Use the keyboard or on-screen buttons: left arrow for the first category, right arrow for the second. If you make an occasional mistake, you will see X; correct your answer rapidly. Classify items as quickly as you can, but also be accurate."},"order":10,"settings":{"maxLength":500}},{"id":"test-instructions","type":"textarea","label":"Test instructions","placeholder":{"enabled":true,"text":"Now a word or image may appear before each object; ignore it. One of three objects may appear each trial. Classify as quickly as possible: left arrow for the first category, right arrow for the second."},"order":11,"settings":{"maxLength":500}},{"id":"show-results-config","type":"checkbox","label":"Show results to respondents","value":"false","order":12}]}'
WHERE name = 'Attribute Testing' AND is_active = 1;
